(()=>{const $=id=>document.getElementById(id);let items=[],curated={},checking=false;const endpoint='https://api.github.com/repos/near/NEPs/pulls?state=open&sort=updated&direction=desc&per_page=20';
function clean(text){return (text||'').replace(/```[\s\S]*?```/g,'').replace(/<!--[\s\S]*?-->/g,'').replace(/!?\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/<[^>]*>/g,'').replace(/^[#>*\-\s]+/gm,'').replace(/\s+/g,' ').trim().split(' ').slice(0,25).join(' ')}
function show(item){const key=String(item.url.split('/').at(-1)),entry=curated[key],known=entry&&entry.updatedAt===item.updatedAt&&entry.title===item.title;$('headlineType').textContent=(item.draft?'Draft proposal':'Open proposal')+' · NEAR';$('headlineTitle').textContent=item.title;$('headlineTime').textContent='Updated '+new Date(item.updatedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});$('headlineSummary').textContent=(known?entry.summary:item.summary)||'This item is open for discussion in NEAR’s proposal repository. Read the source for the proposed changes and their rationale.';$('headlineLink').href=item.url;$('headlineExplanation').hidden=true;$('headlineExplain').textContent='Explain in simple terms';$('headlinePlain').textContent=known?entry.plain:'To understand its effect, check what the proposal changes, whether it has been approved, and when it would take effect. Its title alone does not establish an effect on NEAR price, issuance or buybacks.';$('headlineExplainStatus').textContent=known?'Source-based explanation · saved for this proposal version':'Live AI explanation is not connected yet.';$('headlineDetail').showModal()}
function render(){const parent=$('railItems');parent.replaceChildren();for(const item of [...items].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt))){let url;try{url=new URL(item.url);if(url.origin!=='https://github.com'||!url.pathname.startsWith('/near/NEPs/pull/'))continue}catch{continue}const b=document.createElement('button');b.className='rail-item';b.textContent=item.title;b.title=item.title;b.setAttribute('aria-label',item.title);b.onclick=()=>show(item);parent.append(b)}if(!parent.children.length){const p=document.createElement('p');p.className='quiet';p.textContent='No headlines available.';parent.append(p)}}
async function refresh(){if(checking)return;checking=true;$('railRefresh').disabled=true;try{const r=await fetch(endpoint,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data))throw Error();items=data.map(r=>({title:r.title,url:r.html_url,updatedAt:r.updated_at,createdAt:r.created_at,draft:r.draft,summary:clean(r.body)}));render();$('railStatus').textContent='NEAR proposals · just checked'}catch{$('railStatus').textContent='NEAR proposals · saved headlines'}finally{checking=false;$('railRefresh').disabled=false}}
fetch('./data/catalyst-explanations.json').then(r=>r.json()).then(j=>{curated=j}).catch(()=>{});fetch('./data/catalysts.json').then(r=>r.json()).then(j=>{items=j.items||[];render();$('railStatus').textContent='NEAR proposals · saved '+new Date(j.retrievedAt).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}).catch(()=>render()).finally(refresh);$('railRefresh').onclick=refresh;$('closeHeadline').onclick=()=>$('headlineDetail').close();$('headlineExplain').onclick=()=>{$('headlineExplanation').hidden=!$('headlineExplanation').hidden;$('headlineExplain').textContent=$('headlineExplanation').hidden?'Explain in simple terms':'Hide explanation'};setInterval(()=>{if(!document.hidden)refresh()},300000);
})();
